INSERT INTO `categories` VALUES (1,'数学',1,'考研数学相关资料','2026-03-23 15:30:17'),(2,'英语',2,'考研英语相关资料','2026-03-23 15:30:17'),(3,'政治',3,'考研政治相关资料','2026-03-23 15:30:17'),(4,'专业课',4,'各专业课资料','2026-03-23 15:30:17'),(5,'高等数学',1,'高等数学专项','2026-03-23 15:30:17'),(6,'线性代数',1,'线性代数专项','2026-03-23 15:30:17'),(7,'概率统计',1,'概率论与数理统计','2026-03-23 15:30:17'),(8,'阅读理解',2,'英语阅读专项','2026-03-23 15:30:17'),(9,'写作',2,'英语写作专项','2026-03-23 15:30:17'),(10,'近代史',3,'中国近现代史','2026-03-23 15:30:17'),(11,'马克思主义',3,'马克思主义基本原理','2026-03-23 15:30:17');
