INSERT INTO `material_comments` VALUES (1,2,7,'这份660题按层次来刷很舒服，基础阶段用来查漏补缺很有效。','2026-03-29 01:03:41','2026-03-29 01:03:41'),(2,2,13,'真题分类汇编非常实用，建议先按章节做再整套计时。','2026-03-29 01:03:41','2026-03-29 01:03:41'),(3,2,18,'写作热点总结得很全，背模板时最好配合自己的例子。','2026-03-29 01:03:41','2026-03-29 01:03:41'),(4,3,23,'马原选择题技巧很有帮助，错题复盘后正确率提升明显。','2026-03-29 01:03:41','2026-03-29 01:03:41'),(5,3,26,'主观题模板清晰，冲刺阶段按这个框架背诵很高效。','2026-03-29 01:03:41','2026-03-29 01:03:41'),(6,3,29,'408网络这份资料结构很完整，适合二轮复习串联知识。','2026-03-29 01:03:41','2026-03-29 01:03:41'),(7,1,3,'不错不错','2026-03-29 01:16:50','2026-03-29 01:48:23'),(8,4,14,'很能抓住重点，但是学起来很难','2026-03-29 01:47:43','2026-03-29 01:47:43');
