INSERT INTO `materials` VALUES (1,'高等数学张宇18讲','考研数学高分必备，张宇老师经典讲义，覆盖数学一、二全部考点',5,'数学,高数,张宇,考研',NULL,NULL,NULL,'张宇',4.80,1250,8902,3200,'ACTIVE',1,'2026-03-23 15:30:17','2026-03-26 15:11:17'),(2,'考研英语真题解析2015-2024','近十年考研英语一、二真题完整解析，含翻译和写作范文',8,'英语,真题,阅读,写作',NULL,NULL,NULL,'考研英语研究组',5.00,2,12005,5600,'ACTIVE',1,'2026-03-23 15:30:17','2026-03-27 14:22:50'),(3,'肖秀荣政治精讲精练','考研政治全套资料，肖秀荣老师权威出品，必背知识点汇总',10,'政治,肖秀荣,马原,近代史',NULL,NULL,NULL,'肖秀荣',5.00,2,15012,8900,'ACTIVE',1,'2026-03-23 15:30:17','2026-03-29 01:48:41'),(4,'线性代数李永乐辅导讲义','李永乐老师线性代数全面讲解，题型总结与解题技巧',6,'数学,线性代数,李永乐',NULL,NULL,NULL,'李永乐',4.60,760,5403,2100,'ACTIVE',1,'2026-03-23 15:30:17','2026-03-26 15:11:26'),(5,'概率论与数理统计习题集','考研数学概率部分专项练习，附详细解题过程',7,'数学,概率论,数理统计',NULL,NULL,NULL,'考研数学教研组',4.30,420,3201,1400,'ACTIVE',1,'2026-03-23 15:30:17','2026-03-26 15:11:30'),(6,'考研英语写作模板汇总','大作文小作文高分模板，覆盖常见话题类型',9,'英语,写作,模板,作文',NULL,NULL,NULL,'英语研究中心',5.00,1,7804,4300,'ACTIVE',1,'2026-03-23 15:30:17','2026-03-29 01:52:52'),(7,'高等数学660题分层精练','按基础、强化、冲刺分层设计，覆盖极限、积分、微分方程等核心题型。',5,'数学,高数,习题,分层训练',NULL,NULL,NULL,'研数教研组',3.50,2,11241,4210,'ACTIVE',1,'2026-03-27 17:39:32','2026-03-29 03:41:58'),(8,'高等数学错题归因手册','围绕常见失分点做错因分析，附同类题二次训练建议。',5,'数学,高数,错题,提分',NULL,NULL,NULL,'考研数学工作室',4.50,530,7681,2890,'ACTIVE',1,'2026-03-27 17:39:32','2026-03-29 01:11:21'),(9,'线性代数必会题型100讲','行列式、矩阵、向量组与特征值题型全覆盖，适合二轮复习。',6,'数学,线代,题型,强化',NULL,NULL,NULL,'李老师团队',4.80,920,10450,3970,'ACTIVE',1,'2026-03-27 17:39:32','2026-03-27 17:39:32'),(10,'线代特征值与二次型专题突破','聚焦特征值计算、相似对角化、二次型标准化三大难点。',6,'数学,线代,特征值,二次型',NULL,NULL,NULL,'研数突破营',4.60,480,6520,2380,'ACTIVE',1,'2026-03-27 17:39:32','2026-03-27 17:39:32'),(11,'概率统计公式速记与真题串讲','高频公式一页速记，配套真题应用场景讲解。',7,'数学,概率统计,公式,真题',NULL,NULL,NULL,'概率统计教研组',4.40,410,5870,2010,'ACTIVE',1,'2026-03-27 17:39:32','2026-03-27 17:39:32'),(12,'概率论经典题型500题','按随机变量、分布、数字特征、大数定律分章节刷题。',7,'数学,概率统计,刷题,500题',NULL,NULL,NULL,'考研题库中心',4.60,620,8320,3120,'ACTIVE',1,'2026-03-27 17:39:32','2026-03-27 17:39:32'),(13,'数学一近十年真题分类汇编','将近十年数学一真题按知识点重排，适合阶段性检测。'